import{d as r,C as s,o as g,c as h,a3 as e,E as i,j as a,a as c}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"正易心法·第十四章","description":"《正易心法》第十四章——钻木凿井，人之坎离：坎离为日月之体、天地中气，日月交错生三百六十爻诸卦；辨体用，破所见，归于穷理尽性。","frontmatter":{"title":"正易心法·第十四章","description":"《正易心法》第十四章——钻木凿井，人之坎离：坎离为日月之体、天地中气，日月交错生三百六十爻诸卦；辨体用，破所见，归于穷理尽性。","category":"guide","aliases":["正易心法第十四章","钻木凿井人之坎离","坎离日月"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-14.md","filePath":"yijing/zheng-yi-xin-fa/chapter-14.md","lastUpdated":1790647676000}'),d={name:"yijing/zheng-yi-xin-fa/chapter-14.md"},v=r({...d,setup(u){const t=[{id:"z14-01",label:"一、识取自然",showLabel:!0,sentences:[["钻木凿井，人之坎离。天地坎离，",{text:"识取自然",glossary:"shiquZiran"},"。"]],note:["钻木取火、凿地取水，是人工制造的坎离；天地之间的坎离，要认识并取法自然。（人工的坎离是「用」，天地的坎离是「体」——这一句是全章的纲：**不要把注意力放在可以制造的坎离上，要看那个本来就在的坎离。**）"]},{id:"z14-02",label:"二、乾一阴升为离",showLabel:!0,sentences:[["乾，天也。一阴升于乾之中为离。离为日，则曰",{text:"本天之气",glossary:"bentianZhiqi"},"也。"]],note:["乾是天。一阴升入乾的中爻，形成离。离对应太阳，所以说太阳根本于天（乾）之气。（注意方向：**「升」——坤阴上升入乾**，这是离的生成；与第九章「一阴杂于中」是同一件事，本章从「升入」的角度再说一遍。）"]},{id:"z14-03",label:"三、坤一阳降为坎",showLabel:!0,sentences:[["坤，地也。一阳下降于坤之中为坎。坎为月，则曰",{text:"本地之气",glossary:"bendiZhiqi"},"也。"]],note:["坤是地。一阳降入坤的中爻，形成坎。坎对应月亮，所以说月亮根本于地（坤）之气。（**「降」——乾阳下降入坤**，这是坎的生成。第十三章说坎是「乾水」、是「气之液」，本章给出它的宇宙论定位：坎为月，是地气中含天光。）"]},{id:"z14-04",label:"四、日月交错生诸卦",showLabel:!0,sentences:[["日为天气，自西而下以交于地。月为地气，自东而上以交于天。日月交错，一昼一夜，循环三百六十度，而扰扰万绪起矣，是为三百六十爻，而诸卦生焉。"]],note:["太阳是天气，从西方下落以交于地；月亮是地气，从东方上升以交于天。日月交错，一昼一夜，循环三百六十度，纷繁复杂的万事万物由此而起——这就是三百六十爻，诸卦由此而生。（这是《正易心法》的**宇宙生成论核心**：不是「圣人画卦」，而是「日月运行自然生卦」。一昼一夜就是一次完整的阴阳交媾。）"]},{id:"z14-05",label:"五、坎离天地中气",showLabel:!0,sentences:[["坎离日月，天地之",{text:"中气",glossary:"zhongqi"},"也。"]],note:["坎离日月，是天地的中气（枢纽）。（「中气」一词极准：坎离不是天地的两极，而是**天地之间交通的媒介**——乾阳降到坤中为坎，坤阴升到乾中为离，日月就是天地互相往来的那两个使者。）"]},{id:"z14-06",label:"六、体用之辨",showLabel:!0,sentences:[["仲尼特言水火，而不言日月者，日月其",{text:"体",glossary:"tiyong"},"也，水火其用也。言其用而不言其体，盖欲其设施之广而无碍也。学者不悟，但求之于钻木凿井之间，所失益甚矣。"]],note:["孔子（《系辞传》）只说水火而不说日月，是因为日月是体，水火是用；说用而不说体，是为了让应用广泛而不受限制。学者不能领悟，只在钻木凿井（普通水火）上求坎离，所失就更严重了。（孔子说水火的好处：**说「日月」只能想到天文现象；说「水火」则可以推广到自然水火、人体肾水心火、炼丹铅汞、社会柔刚——「设施之广而无碍」。** 但代价是：学者忘了日月之体。）"]},{id:"z14-07",label:"七、男女构精之象",showLabel:!0,sentences:[["又论，月上于天，日入于地，男女构精之象。一来一往，卦画有",{text:"中通",glossary:"zhongtong"},"之象。此所谓观于",{text:"卦脉",glossary:"guamai"},"，理则昭然也。"]],note:["再论：月亮升于天，太阳入于地，这是男女交合构精的象。一来一往，卦画中有中间贯通的象。（「中通」指坎离的中爻：**离的中爻是阴（虚），可以接纳；坎的中爻是阳（实），可以给予**——坎中之阳填入离中之虚，正是「取坎填离」的宇宙原型，也是「月光来自太阳」的道理。这一句又把第七章的「卦脉」接上了。）"]},{id:"z14-08",label:"八、破所见而穷理尽性",showLabel:!0,sentences:[["有谓理实昭然，若山者自天之坠也。《传》曰：“自有宇宙，便有此山。”又曰：“星陨为石。”推此意，则山自天坠无疑。而世曰：“山者，地之物。”以所见者言之耳。至月风雷雨，皆自地出也。而世曰：“月风雷雨，天之物。”亦以所见者言之耳。世以所见如此！苟徇其所见，则天地万物，皆所不晓。审知《易》者，所以",{text:"穷理尽性",glossary:"qionglijinxing"},"也。学者不可不留意邪！"]],note:["（末段是全书认识论批判的顶点。）道理确实昭然，比如山是从天上坠落的：《传》说「自有宇宙，便有此山」，又说「星陨为石」——推此意，山自天坠无疑。而世人说「山是地上的东西」，不过是以眼睛所见来说而已。至于月、风、雷、雨，都是从地中出来的；而世人说它们是「天上的东西」，同样以所见为准。世人都以所见为准！若只顺从眼睛所见，则天地万物都无法真正了解。**真正懂得《易》的人，正是用来穷究事物之理、完全实现本性的。**（「穷理尽性」语出《说卦传》：《易》的最终目的不是算卦预测，而是穷究万物之理、进而实现自己的本性——**穷理是手段，尽性是目的**。这也回收了第一章「山自天上而坠」的钩子。）"]}],l=[{id:"shiquZiran",term:"识取自然",pinyin:"shí qǔ zì rán",meaning:"认识并取法自然。天地坎离才是根本，人工（钻木凿井）是末。"},{id:"bentianZhiqi",term:"本天之气",pinyin:"běn tiān zhī qì",meaning:"根本于天（乾）的气。离虽有阴，本质是乾阳外显，故为日。"},{id:"bendiZhiqi",term:"本地之气",pinyin:"běn dì zhī qì",meaning:"根本于地（坤）的气。坎虽有阳，本质是坤阴内藏，故为月。"},{id:"zhongqi",term:"中气",pinyin:"zhōng qì",meaning:"天地之间的枢纽之气。坎离居中，是天地交通的媒介。"},{id:"tiyong",term:"体与用",pinyin:"tǐ yǔ yòng",meaning:"日月是体（本质、根源），水火是用（功能、应用）。孔子言水火不言日月，是为「设施之广而无碍」。"},{id:"zhongtong",term:"中通",pinyin:"zhōng tōng",meaning:"中间贯通的象。离之中爻虚可纳，坎之中爻实可予——坎中之阳填入离中之虚。"},{id:"guamai",term:"卦脉",pinyin:"guà mài",meaning:"卦画的内在脉络。第七章核心概念，本章再次点出（「观于卦脉，理则昭然」）。"},{id:"qionglijinxing",term:"穷理尽性",pinyin:"qióng lǐ jìn xìng",meaning:"穷究事物之理，完全实现本性。语出《说卦传》，是易学的最高目标：穷理是手段，尽性是目的。"}];return(b,n)=>{const p=s("DaoTextReading"),o=s("DaoKeywordCards");return g(),h("div",null,[n[0]||(n[0]=e("",25)),i(p,{colophon:"识取自然 · 日月生卦 · 体用之辨 · 穷理尽性",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第十四章原文",sections:t,glossary:l}),n[1]||(n[1]=a("blockquote",null,[a("p",null,"注：本页依所据底本录入，用字随底本，不作统一。")],-1)),n[2]||(n[2]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[c("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),i(o,{items:[{term:"天地坎离",pinyin:["kǎn","lí"],meaning:"坎离是日月之体、天地中气：离为日（本天之气），坎为月（本地之气）。人工的钻木凿井只是其「用」。"},{term:"日月生卦",pinyin:["rì","yuè"],meaning:"日月交错、一昼一夜、循环三百六十度＝三百六十爻，诸卦生焉。卦是日月运行自然生成，非圣人创造。"},{term:"体用之辨",pinyin:["tǐ","yòng"],meaning:"日月为体，水火为用。孔子言水火不言日月，是为应用广泛；但学者执用忘体，便成了「钻木凿井」。"},{term:"中通之象",pinyin:["zhōng","tōng"],meaning:"离之中爻虚可纳，坎之中爻实可予——坎中之阳填入离中之虚，即「取坎填离」的宇宙原型。"},{term:"山自天坠",pinyin:["shān","zì"],meaning:"艮＝一阳在二阴上＝乾上爻落入坤中，故山自天坠。以「星陨为石」为验证。回收第一章钩子。"},{term:"穷理尽性",pinyin:["qióng","lǐ"],meaning:"《说卦传》语，是《易》的最终目的：穷究万物之理（去表象之蔽），完全实现本性（尽乾为圣、尽坤为贤）。"}]}),n[3]||(n[3]=e("",30))])}}});export{y as __pageData,v as default};
